package com.cappleapple.astralrepository.platform.registry;
import net.minecraft.core.Registry;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.*;
public final class DeferredRegister<T>{private final ResourceKey<? extends Registry<T>> registry;private final String namespace;private final java.util.List<RegistryObject<? extends T>> entries=new java.util.ArrayList<>();private DeferredRegister(ResourceKey<? extends Registry<T>> registry,String namespace){this.registry=registry;this.namespace=namespace;}public static <T> DeferredRegister<T> create(ResourceKey<? extends Registry<T>> registry,String namespace){return new DeferredRegister<>(registry,namespace);}public <V extends T> RegistryObject<V> register(String path,java.util.function.Supplier<V> factory){var value=new RegistryObject<V>(new ResourceLocation(namespace,path),factory);entries.add(value);return value;}public java.util.Collection<RegistryObject<? extends T>> getEntries(){return java.util.List.copyOf(entries);}@SuppressWarnings("unchecked") public void register(){Registry<T> target=(Registry<T>)BuiltInRegistries.REGISTRY.get(registry.location());for(var entry:entries)Registry.register(target,entry.getId(),entry.get());}}
